xinshengCustomCss:
/* 0. 重置 */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; background: transparent !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; font-family: 'Georgia', 'Noto Serif SC', serif !important; }
.xt-root::-webkit-scrollbar { width: 0 !important; display: none !important; }

/* 根容器 overflow:visible 图片不被裁剪，min-height保证内容不溢出 */
.xt-root {
    width: 320px !important; min-height: 480px !important; height: auto !important;
    background: transparent !important;
    border: none !important; border-radius: 0 !important;
    position: relative !important;
    margin: 50px auto 100px !important;
    overflow: visible !important;
    box-shadow: none !important;
}
/* 白色卡片面板 */
.xt-root::before {
    content: '' !important; position: absolute !important;
    top: 0 !important; left: 0 !important; width: 100% !important; height: 100% !important;
    background: #ffffff !important;
    border: 1px solid #e8e8e8 !important;
    border-radius: 0 !important;
    z-index: 1 !important;
    box-shadow: 0 2px 12px rgba(0,0,0,0.04) !important;
    pointer-events: none !important;
}

/* ================= 内容区 ================= */

/* 1. 顶部浅灰色色带 + 标题 */
.xt-text:nth-of-type(1) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; height: 48px !important;
    background: #f0f0f0 !important;
    line-height: 48px !important; padding: 0 20px !important;
    font-size: 14px !important; font-weight: bold !important; color: #000000 !important;
    letter-spacing: 1px !important;
    text-align: center !important;
}
.xt-text:nth-of-type(1)::before {
    content: '✦ \A0 ☆ \A0 ✧' !important; position: absolute !important; top: 6px !important; left: 12px !important;
    font-size: 9px !important; color: #c0c0c0 !important; letter-spacing: 2px !important; line-height: normal !important;
}
.xt-text:nth-of-type(1)::after {
    content: '☆ \A0\A0 ✦ \A0\A0 ✧ \A0\A0 ☆' !important; position: absolute !important; top: 6px !important; right: 12px !important;
    font-size: 8px !important; color: #d0d0d0 !important; letter-spacing: 1px !important; line-height: normal !important;
}

/* 2. TITLE 栏 */
.xt-text:nth-of-type(2) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; padding: 12px 20px 10px !important;
    font-size: 11px !important; color: #707070 !important; letter-spacing: 1px !important;
}
.xt-text:nth-of-type(2)::before {
    content: ' HEART' !important; position: absolute !important; top: 12px !important; left: 20px !important;
    font-size: 9px !important; color: #909090 !important; text-transform: uppercase !important; letter-spacing: 2px !important;
}
.xt-text:nth-of-type(2)::after {
    content: '' !important; position: absolute !important; bottom: 0 !important;
    left: 50% !important; transform: translateX(-50%) !important; /* 居中 */
    width: 280px !important; height: 1px !important; background: #e8e8e8 !important;
}

/* 3. 内容区1 */
.xt-text:nth-of-type(3) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; padding: 14px 22px !important;
    font-size: 12.5px !important; color: #4a4a4a !important; line-height: 1.8 !important;
}
.xt-text:nth-of-type(3)::before {
    content: '§' !important; position: absolute !important; top: 14px !important; left: 9px !important;
    font-size: 13px !important; color: #c0c0c0 !important;
}
.xt-text:nth-of-type(3)::after {
    content: '' !important; position: absolute !important; bottom: 0 !important;
    left: 50% !important; transform: translateX(-50%) !important;
    width: 280px !important; height: 1px !important; background: #e8e8e8 !important;
}

/* 4. 内容区2 */
.xt-text:nth-of-type(4) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; padding: 12px 22px !important;
    font-size: 12px !important; color: #5e5e5e !important; line-height: 1.7 !important;
}

/* 5. 分隔装饰 (线条绝对居中) */
.xt-text:nth-of-type(5) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; height: 28px !important;
}
.xt-text:nth-of-type(5)::before {
    content: '' !important; position: absolute !important; top: 50% !important;
    left: 50% !important; transform: translate(-50%, -50%) !important;
    width: 280px !important; height: 1px !important; background: #e2e2e2 !important;
}
.xt-text:nth-of-type(5)::after {
    content: '✦' !important; position: absolute !important; top: 50% !important; left: 50% !important;
    transform: translate(-50%, -50%) !important; background: #ffffff !important; padding: 0 10px !important;
    font-size: 10px !important; color: #c0c0c0 !important;
}

/* 6. 内容区3 */
.xt-text:nth-of-type(6) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; padding: 12px 22px !important;
    font-size: 12px !important; color: #5e5e5e !important; line-height: 1.7 !important;
}
.xt-text:nth-of-type(6)::after {
    content: '' !important; position: absolute !important; bottom: 0 !important;
    left: 50% !important; transform: translateX(-50%) !important;
    width: 280px !important; height: 1px !important; background: #e8e8e8 !important;
}

/* 7. 结尾 */
.xt-text:nth-of-type(7) {
    position: relative !important; z-index: 2 !important;
    width: 100% !important; padding: 16px 22px 20px !important;
    font-size: 11px !important; color: #8a8a8a !important; line-height: 1.6 !important;
    text-align: center !important; font-style: italic !important;
}
.xt-text:nth-of-type(7)::after {
    content: '✦ 매일매일 조금이라도 행복하자 ✦' !important; display: block !important; margin-top: 14px !important;
    font-size: 9px !important; color: #c0c0c0 !important; letter-spacing: 3px !important; font-style: normal !important;
}

/* ================= 图片区 (全部不被裁剪) ================= */

/* 8. 倾斜照片 (卡片背后露边角) */
.xt-text:nth-of-type(8) {
    position: absolute !important;
    bottom: 50px !important;       /* 🔧 上下位置 */
    left: 50% !important;           /* 🔧 左右位置 */
    transform: translateX(-50%) rotate(30deg) !important; /* 🔧 旋转角度 */
    width: 280px !important;        /* 🔧 图片宽度 */
    height: 370px !important;       /* 🔧 图片高度 */
    background: url('https://i.postimg.cc/BQ02nqNj/IMG-2319.jpg') center/cover no-repeat !important;
    z-index: 0 !important;
    border-radius: 4px !important;
    box-shadow: 0 4px 16px rgba(0,0,0,0.1) !important;
}

/* 9. 顶部浮动图片 */
.xt-text:nth-of-type(9) {
    position: absolute !important;
    top: -50px !important;           /* 🔧 上下位置 */
    left: 50% !important;            /* 🔧 左右位置 */
    transform: translateX(-50%) !important;
    width: 200px !important;         /* 🔧 图片宽度 */
    height: 80px !important;         /* 🔧 图片高度 */
    background: url('https://i.postimg.cc/jdbySsvj/IMG-2323.png') center/contain no-repeat !important;
    z-index: 10 !important;
}

/* 10. 侧边浮动图片 */
.xt-text:nth-of-type(10) {
    position: absolute !important;
    top: 223px !important;            /* 🔧 上下位置 */
    right: -80px !important;          /* 🔧 左右位置 */
    width: 200px !important;           /* 🔧 图片宽度 */
    height: 300px !important;         /* 🔧 图片高度 */
    background: url('https://i.postimg.cc/SNhcxyVQ/IMG-2329.png') center/contain no-repeat !important;
    z-index: 10 !important;
}

/* 11. 底部浮动图片 */
.xt-text:nth-of-type(11) {
    position: absolute !important;
    bottom: -60px !important;         /* 🔧 上下位置 */
    left: 50% !important;             /* 🔧 左右位置 */
    transform: translateX(-50%) !important;
    width: 430px !important;          /* 🔧 图片宽度 */
    height: 110px !important;          /* 🔧 图片高度 */
    background: url('https://i.postimg.cc/hj4T1Mzx/IMG-2336.png') center/contain no-repeat !important;
    z-index: 10 !important;
}

/* 12. 左上贴图浮动 */
.xt-text:nth-of-type(12) {
    position: absolute !important;
    top: 225px !important;            /* 🔧 上下位置 */
    left: -75px !important;           /* 🔧 左右位置 */
    width: 190px !important;           /* 🔧 图片宽度 */
    height: 290px !important;          /* 🔧 图片高度 */
    background: url('https://i.postimg.cc/yYH08Vnz/IMG-2330.png') center/contain no-repeat !important;
    z-index: 10 !important;
}

